<?php
require_once __DIR__.'/../config/auth.php';require_role('owner');$pageTitle='Moderasi Moments & Review';$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$type=(string)($_POST['type']??'');$action=(string)($_POST['action']??'');$id=(int)($_POST['id']??0);$status=match($action){'approve'=>'approved','reject'=>'rejected',default=>''};try{if(!$status||!in_array($type,['moment','review'],true))throw new RuntimeException('aksi moderasi tidak valid.');if($type==='moment'){$pdo->prepare('UPDATE moments SET status=? WHERE id=?')->execute([$status,$id]);log_activity('moderate_moment',$status.' ID '.$id);}else{$pdo->prepare('UPDATE reviews SET status=? WHERE id=?')->execute([$status,$id]);log_activity('moderate_review',$status.' ID '.$id);}$message='status moderasi diperbarui.';}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'gagal mengubah status moderasi.';}}
$filter=(string)($_GET['filter']??'pending');$valid=['pending','approved','rejected','all'];if(!in_array($filter,$valid,true))$filter='pending';$cond=$filter==='all'?'1=1':'status='.$pdo->quote($filter);$moments=dbq("SELECT * FROM moments WHERE $cond ORDER BY created_at DESC LIMIT 100")->fetchAll();$reviews=dbq("SELECT r.*,o.kode_pesanan,o.nama_pelanggan FROM reviews r JOIN orders o ON o.id=r.order_id WHERE $cond ORDER BY r.created_at DESC LIMIT 100")->fetchAll();
require __DIR__.'/../includes/admin-header.php'; ?>
<?php if($message):?><div class="flash flash-ok"><?= h($message) ?></div><?php endif;?><?php if($error):?><div class="flash flash-error"><?= h($error) ?></div><?php endif;?><div class="flex flex-wrap gap-2 mb-5 no-print"><?php foreach(['pending'=>'Menunggu','approved'=>'Disetujui','rejected'=>'Ditolak','all'=>'Semua'] as $f=>$label):?><a class="px-4 py-2 rounded-full text-sm <?= $filter===$f?'bg-coffee text-white':'bg-white border border-coffee/10' ?>" href="?filter=<?= h($f) ?>"><?= h($label) ?></a><?php endforeach;?></div><section class="card p-5"><div class="flex justify-between items-center gap-3"><div><h2 class="font-serif text-2xl">Kopiah Moments</h2><p class="text-xs text-coffee/55 mt-1">foto yang disetujui akan tampil di galeri pelanggan.</p></div><span class="status-pill"><?= count($moments) ?> foto</span></div><div class="grid sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 mt-5"><?php foreach($moments as $m):?><article class="border border-coffee/10 bg-white rounded-2xl overflow-hidden"><img src="<?= h(BASE_URL.'/'.$m['file_path']) ?>" class="w-full aspect-[4/3] object-cover" alt="Foto momen"><div class="p-3"><div class="flex items-center justify-between gap-2"><b class="text-sm"><?= h($m['nama_pelanggan']?:'Tanpa nama') ?></b><span class="status-pill <?= $m['status']==='approved'?'status-green':($m['status']==='rejected'?'status-red':'status-orange') ?>"><?= h($m['status']) ?></span></div><p class="text-xs text-coffee/65 mt-2 leading-5"><?= h($m['caption']) ?></p><p class="text-[10px] text-coffee/40 mt-2"><?= h($m['tipe_foto']) ?> · <?= h($m['created_at']) ?></p><?php if($m['status']!=='approved'):?><form method="post" class="flex gap-2 mt-3"><input type="hidden" name="_csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="type" value="moment"><input type="hidden" name="id" value="<?= (int)$m['id'] ?>"><button class="btn btn-sage !py-2 !px-3 !text-xs flex-1" name="action" value="approve">Setujui</button><button class="btn btn-light !py-2 !px-3 !text-xs" name="action" value="reject">Tolak</button></form><?php else:?><form method="post" class="mt-3"><input type="hidden" name="_csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="type" value="moment"><input type="hidden" name="id" value="<?= (int)$m['id'] ?>"><button class="text-xs underline text-red-700" name="action" value="reject">Tarik dari galeri</button></form><?php endif;?></div></article><?php endforeach;?><?php if(!$moments):?><p class="text-sm text-coffee/55">tidak ada foto pada filter ini.</p><?php endif;?></div></section>
<section class="card p-5 mt-5"><div class="flex justify-between items-center"><div><h2 class="font-serif text-2xl">Review pelanggan</h2><p class="text-xs text-coffee/55 mt-1">ulasan baru menunggu persetujuan.</p></div><span class="status-pill"><?= count($reviews) ?> ulasan</span></div><div class="table-wrap mt-4"><table class="admin-table"><thead><tr><th>Pelanggan</th><th>Rating</th><th>Komentar</th><th>Pesanan</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($reviews as $r):?><tr><td><?= h($r['nama']) ?></td><td><span class="rating"><?= str_repeat('★',(int)$r['rating']) ?></span></td><td><?= h($r['komentar']) ?></td><td><?= h($r['kode_pesanan']) ?></td><td><span class="status-pill <?= $r['status']==='approved'?'status-green':($r['status']==='rejected'?'status-red':'status-orange') ?>"><?= h($r['status']) ?></span></td><td><?php if($r['status']!=='approved'):?><form method="post" class="flex gap-2"><input type="hidden" name="_csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="type" value="review"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="text-xs underline" name="action" value="approve">Setujui</button><button class="text-xs underline text-red-700" name="action" value="reject">Tolak</button></form><?php else:?><form method="post"><input type="hidden" name="_csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="type" value="review"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="text-xs underline text-red-700" name="action" value="reject">Tarik</button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$reviews):?><tr><td colspan="6">belum ada review pada filter ini.</td></tr><?php endif;?></tbody></table></div></section><?php require __DIR__.'/../includes/admin-footer.php'; ?>
